/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name, table_operation, db_user,
        operation_description, operation_date,
        operation_status
    )
    VALUES (
        'tb_people', 'Create', USER(),
        CONCAT(
            'person_ID=', NEW.person_ID,
            ', user_ID=',
            COALESCE(CAST(NEW.user_ID AS CHAR), 'NULL'),
            ', given_names=', NEW.given_names,
            ', family_names=',
            COALESCE(NEW.family_names, 'NULL'),
            ', status=', NEW.status
        ),
        CURRENT_TIMESTAMP, b'1'
    );
END */;;
