    INSERT INTO tb_logs
        (table_name, table_operation, db_user,
         operation_description, operation_date,
         operation_status)
    VALUES
        ('tb_users', 'Create', USER(),
         CONCAT(
             'Usuario creado. ID=', NEW.ID,
             ', email=', NEW.email,
