CREATE DEFINER=`root`@`localhost` PROCEDURE `new_procedure`()
BEGIN
    DECLARE v_i INT DEFAULT 0;
    DECLARE v_user_id INT UNSIGNED;
    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_password VARCHAR(100);
    DECLARE v_nombre VARCHAR(150);
    DECLARE v_apellido VARCHAR(150);
    DECLARE v_pais CHAR(2);
    DECLARE v_genero VARCHAR(30);
    DECLARE v_edad INT;
    DECLARE v_nacimiento DATE;
    DECLARE v_telefono VARCHAR(25);
    DECLARE v_nombres JSON;
    DECLARE v_apellidos JSON;
    DECLARE v_paises JSON;
    DECLARE v_indice INT;

    IF p_cantidad < 1
       OR p_edad_min < 0
       OR p_edad_max < p_edad_min
       OR p_activos < 0
       OR p_activos > p_cantidad
       OR p_modo_pais NOT IN ('USA', 'MULTI') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Parametros de prueba invalidos';
    END IF;

    SET v_paises = JSON_ARRAY(
        'US','MX','CA','GB','ES',
        'FR','BR','JP','KR','DE'
    );

    WHILE v_i < p_cantidad DO

        IF p_modo_pais = 'USA' THEN
            SET v_pais = 'US';
        ELSE
            SET v_pais = JSON_UNQUOTE(
                JSON_EXTRACT(
                    v_paises,
                    CONCAT(
                        '$[',
                        FLOOR(RAND() * JSON_LENGTH(v_paises)),
                        ']'
                    )
                )
            );
        END IF;

        CASE v_pais
            WHEN 'US' THEN
                SET v_nombres = JSON_ARRAY(
                    'James','Olivia','William','Emma',
                    'Benjamin','Charlotte','Henry','Amelia'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Smith','Johnson','Brown','Williams',
                    'Jones','Miller','Davis','Wilson'
                );

            WHEN 'MX' THEN
                SET v_nombres = JSON_ARRAY(
                    'Santiago','Sofia','Mateo','Valentina',
                    'Sebastian','Camila','Diego','Ximena'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Hernandez','Garcia','Martinez','Lopez',
                    'Gonzalez','Perez','Rodriguez','Sanchez'
                );

            WHEN 'CA' THEN
                SET v_nombres = JSON_ARRAY(
                    'Liam','Noah','Olivia','Emma',
                    'Ethan','Chloe','Oliver','Ava'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Smith','Brown','Tremblay','Martin',
                    'Roy','Wilson','MacDonald','Gagnon'
                );

            WHEN 'GB' THEN
                SET v_nombres = JSON_ARRAY(
                    'Oliver','George','Harry','Jack',
                    'Amelia','Isla','Freya','Emily'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Smith','Jones','Williams','Brown',
                    'Taylor','Davies','Wilson','Evans'
                );

            WHEN 'ES' THEN
                SET v_nombres = JSON_ARRAY(
                    'Hugo','Martin','Lucas','Mateo',
                    'Lucia','Martina','Sofia','Julia'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Garcia','Rodriguez','Gonzalez','Fernandez',
                    'Lopez','Martinez','Sanchez','Perez'
                );

            WHEN 'FR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Gabriel','Louis','Raphael','Jules',
                    'Emma','Jade','Louise','Alice'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Martin','Bernard','Dubois','Thomas',
                    'Robert','Richard','Petit','Durand'
                );

            WHEN 'BR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Miguel','Arthur','Heitor','Gabriel',
                    'Helena','Alice','Laura','Valentina'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Silva','Santos','Oliveira','Souza',
                    'Pereira','Costa','Rodrigues','Almeida'
                );

            WHEN 'JP' THEN
                SET v_nombres = JSON_ARRAY(
                    'Haruto','Ren','Yuto','Sota',
                    'Yui','Hina','Aoi','Sakura'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Sato','Suzuki','Takahashi','Tanaka',
                    'Watanabe','Ito','Yamamoto','Nakamura'
                );

            WHEN 'KR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Min-jun','Seo-jun','Do-yun','Ji-ho',
                    'Seo-yeon','Ji-woo','Ha-eun','Min-seo'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Kim','Lee','Park','Choi',
                    'Jung','Kang','Cho','Yoon'
                );

            WHEN 'DE' THEN
                SET v_nombres = JSON_ARRAY(
                    'Leon','Paul','Felix','Lukas',
                    'Emilia','Mia','Hannah','Lina'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Mueller','Schmidt','Schneider','Fischer',
                    'Weber','Meyer','Wagner','Becker'
                );
        END CASE;

        SET v_indice = FLOOR(
            RAND() * JSON_LENGTH(v_nombres)
        );

        SET v_nombre = JSON_UNQUOTE(
            JSON_EXTRACT(
                v_nombres,
                CONCAT('$[', v_indice, ']')
            )
        );

        SET v_indice = FLOOR(
            RAND() * JSON_LENGTH(v_apellidos)
        );

        SET v_apellido = JSON_UNQUOTE(
            JSON_EXTRACT(
                v_apellidos,
                CONCAT('$[', v_indice, ']')
            )
        );

        SET v_edad = p_edad_min
            + FLOOR(
                RAND() * (p_edad_max - p_edad_min + 1)
            );

        SET v_nacimiento = DATE_SUB(
            DATE_SUB(CURDATE(), INTERVAL v_edad YEAR),
            INTERVAL FLOOR(RAND() * 300) DAY
        );

        SET v_genero = ELT(
            FLOOR(RAND() * 3) + 1,
            'Hombre',
            'Mujer',
            'Prefiero no decirlo'
        );

        SET v_email = CONCAT(
            'prueba.',
            REPLACE(UUID(), '-', ''),
            '@example.com'
        );

        SET v_nick = CONCAT(
            'test_',
            REPLACE(UUID(), '-', '')
        );

        SET v_password = CONCAT(
            'Prueba_',
            LEFT(REPLACE(UUID(), '-', ''), 20),
            '!'
        );

        SET v_telefono = CONCAT(
            '+',
            CASE v_pais
                WHEN 'US' THEN '1'
                WHEN 'MX' THEN '52'
                WHEN 'CA' THEN '1'
                WHEN 'GB' THEN '44'
                WHEN 'ES' THEN '34'
                WHEN 'FR' THEN '33'
                WHEN 'BR' THEN '55'
                WHEN 'JP' THEN '81'
                WHEN 'KR' THEN '82'
                WHEN 'DE' THEN '49'
            END,
            '000000',
            LPAD(v_i MOD 10000, 4, '0')
        );

        CALL sp_register_new_user(
            v_email,
            v_nick,
            v_password,
            NULL,
            v_nombre,
            v_apellido,
            v_nacimiento,
            v_genero,
            v_pais,
            v_telefono
        );

        SET v_user_id = LAST_INSERT_ID();

        IF v_i >= p_activos THEN
            UPDATE tb_users
            SET status = b'0'
            WHERE ID = v_user_id;
        END IF;

        SET v_i = v_i + 1;

    END WHILE;

    SELECT
        p_cantidad AS cantidad_solicitada,
        p_activos AS activos_solicitados,
        p_cantidad - p_activos AS inactivos_solicitados,
        p_modo_pais AS modo_pais,
        p_edad_min AS edad_minima,
        p_edad_max AS edad_maxima;

END ;;
