                    'Gonzalez','Perez','Rodriguez','Sanchez'
                );

            WHEN 'CA' THEN
                SET v_nombres = JSON_ARRAY(
                    'Liam','Noah','Olivia','Emma',
                    'Ethan','Chloe','Oliver','Ava'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Smith','Brown','Tremblay','Martin',
                    'Roy','Wilson','MacDonald','Gagnon'
                );

            WHEN 'GB' THEN
                SET v_nombres = JSON_ARRAY(
                    'Oliver','George','Harry','Jack',
                    'Amelia','Isla','Freya','Emily'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Smith','Jones','Williams','Brown',
                    'Taylor','Davies','Wilson','Evans'
                );

            WHEN 'ES' THEN
                SET v_nombres = JSON_ARRAY(
                    'Hugo','Martin','Lucas','Mateo',
                    'Lucia','Martina','Sofia','Julia'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Garcia','Rodriguez','Gonzalez','Fernandez',
                    'Lopez','Martinez','Sanchez','Perez'
                );

            WHEN 'FR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Gabriel','Louis','Raphael','Jules',
                    'Emma','Jade','Louise','Alice'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Martin','Bernard','Dubois','Thomas',
                    'Robert','Richard','Petit','Durand'
                );

            WHEN 'BR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Miguel','Arthur','Heitor','Gabriel',
                    'Helena','Alice','Laura','Valentina'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Silva','Santos','Oliveira','Souza',
                    'Pereira','Costa','Rodrigues','Almeida'
                );

            WHEN 'JP' THEN
                SET v_nombres = JSON_ARRAY(
                    'Haruto','Ren','Yuto','Sota',
                    'Yui','Hina','Aoi','Sakura'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Sato','Suzuki','Takahashi','Tanaka',
                    'Watanabe','Ito','Yamamoto','Nakamura'
                );

            WHEN 'KR' THEN
                SET v_nombres = JSON_ARRAY(
                    'Min-jun','Seo-jun','Do-yun','Ji-ho',
                    'Seo-yeon','Ji-woo','Ha-eun','Min-seo'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Kim','Lee','Park','Choi',
                    'Jung','Kang','Cho','Yoon'
                );

            WHEN 'DE' THEN
                SET v_nombres = JSON_ARRAY(
                    'Leon','Paul','Felix','Lukas',
                    'Emilia','Mia','Hannah','Lina'
                );
                SET v_apellidos = JSON_ARRAY(
                    'Mueller','Schmidt','Schneider','Fischer',
                    'Weber','Meyer','Wagner','Becker'
                );
        END CASE;

        SET v_indice = FLOOR(
            RAND() * JSON_LENGTH(v_nombres)
        );

        SET v_nombre = JSON_UNQUOTE(
            JSON_EXTRACT(
                v_nombres,
                CONCAT('$[', v_indice, ']')
            )
        );

        SET v_indice = FLOOR(
            RAND() * JSON_LENGTH(v_apellidos)
        );

        SET v_apellido = JSON_UNQUOTE(
            JSON_EXTRACT(
                v_apellidos,
                CONCAT('$[', v_indice, ']')
            )
        );

        SET v_edad = p_edad_min
            + FLOOR(
                RAND() * (p_edad_max - p_edad_min + 1)
            );

        SET v_nacimiento = DATE_SUB(
            DATE_SUB(CURDATE(), INTERVAL v_edad YEAR),
            INTERVAL FLOOR(RAND() * 300) DAY
        );

        SET v_genero = ELT(
            FLOOR(RAND() * 3) + 1,
            'Hombre',
            'Mujer',
            'Prefiero no decirlo'
        );

        SET v_email = CONCAT(
            'prueba.',
            REPLACE(UUID(), '-', ''),
            '@example.com'
        );

        SET v_nick = CONCAT(
            'test_',
            REPLACE(UUID(), '-', '')
        );

        SET v_password = CONCAT(
            'Prueba_',
            LEFT(REPLACE(UUID(), '-', ''), 20),
            '!'
        );

        SET v_telefono = CONCAT(
            '+',
            CASE v_pais
                WHEN 'US' THEN '1'
                WHEN 'MX' THEN '52'
                WHEN 'CA' THEN '1'
                WHEN 'GB' THEN '44'
                WHEN 'ES' THEN '34'
                WHEN 'FR' THEN '33'
                WHEN 'BR' THEN '55'
                WHEN 'JP' THEN '81'
                WHEN 'KR' THEN '82'
                WHEN 'DE' THEN '49'
            END,
            '000000',
            LPAD(v_i MOD 10000, 4, '0')
        );

        CALL sp_register_new_user(
            v_email,
            v_nick,
            v_password,
            NULL,
            v_nombre,
            v_apellido,
            v_nacimiento,
            v_genero,
            v_pais,
            v_telefono
        );

        SET v_user_id = LAST_INSERT_ID();

        IF v_i >= p_activos THEN
            UPDATE tb_users
            SET status = b'0'
            WHERE ID = v_user_id;
        END IF;

        SET v_i = v_i + 1;

    END WHILE;

    SELECT
        p_cantidad AS cantidad_solicitada,
        p_activos AS activos_solicitados,
        p_cantidad - p_activos AS inactivos_solicitados,
        p_modo_pais AS modo_pais,
        p_edad_min AS edad_minima,
        p_edad_max AS edad_maxima;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_register_new_user` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_register_new_user`(
    IN p_email          VARCHAR(100),
    IN p_nick           VARCHAR(50),
    IN p_password       VARCHAR(100),
    IN p_courtesy_title VARCHAR(20),
    IN p_given_names    VARCHAR(150),
    IN p_family_names   VARCHAR(150),
    IN p_birth_date     DATE,
    IN p_gender         VARCHAR(30),
    IN p_country_code   VARCHAR(50),
    IN p_phone          VARCHAR(25)
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_db_user   VARCHAR(32);
    DECLARE v_has_role  INT DEFAULT 0;
    DECLARE v_count     INT DEFAULT 0;
    DECLARE v_user_id   INT UNSIGNED;
    DECLARE v_person_id BIGINT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    DECLARE EXIT HANDLER FOR 1062
    BEGIN
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El correo o el nick ya se encuentran registrados';
    END;

    
    SET v_db_user = SUBSTRING_INDEX(USER(), '@', 1);

    
    SELECT COUNT(*)
    INTO v_has_role
    FROM mysql.role_edges re
    WHERE re.TO_USER = v_db_user
      AND re.TO_HOST = '%'
      AND re.FROM_HOST = '%'
      AND re.FROM_USER IN (
          'superadmin',
          'admin',
          'support',
          'user_not_registered'
      );

    IF v_has_role = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Acceso denegado: rol no autorizado';
    END IF;

    
    SET p_email          = LOWER(TRIM(p_email));
    SET p_nick           = TRIM(p_nick);
    SET p_given_names    = TRIM(p_given_names);
    SET p_family_names   = NULLIF(TRIM(p_family_names), '');
    SET p_courtesy_title = NULLIF(TRIM(p_courtesy_title), '');
    SET p_gender         = COALESCE(NULLIF(TRIM(p_gender), ''), 'Prefiero no decirlo');
    SET p_country_code   = NULLIF(UPPER(TRIM(p_country_code)), '');
    SET p_phone          = NULLIF(TRIM(p_phone), '');

    
    IF p_email IS NULL OR p_email NOT REGEXP '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El correo electrónico es inválido';
    END IF;

    IF p_nick IS NULL OR CHAR_LENGTH(p_nick) < 3 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El nick debe tener al menos 3 caracteres';
    END IF;

    IF p_password IS NULL OR CHAR_LENGTH(p_password) < 8 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La contraseña debe tener al menos 8 caracteres';
    END IF;

    
    IF p_given_names IS NULL OR p_given_names = '' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El nombre es obligatorio';
    END IF;

    IF p_birth_date IS NOT NULL
       AND (p_birth_date > CURRENT_DATE OR p_birth_date < '1900-01-01') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'La fecha de nacimiento es inválida';
    END IF;

    IF p_gender NOT IN ('Hombre', 'Mujer', 'Prefiero no decirlo') THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El género debe ser Hombre, Mujer o Prefiero no decirlo';
    END IF;

    IF p_country_code IS NOT NULL AND p_country_code NOT REGEXP '^[A-Z]{2}$' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El código de país debe tener 2 letras (ISO)';
    END IF;

    IF p_phone IS NOT NULL AND p_phone NOT REGEXP '^[0-9+() -]{7,25}$' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El teléfono es inválido';
    END IF;

    
    SELECT COUNT(*) INTO v_count FROM tb_users WHERE email = p_email;
    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El correo electrónico ya se encuentra registrado';
    END IF;

    SELECT COUNT(*) INTO v_count FROM tb_users WHERE nick = p_nick;
    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El nick ya se encuentra en uso';
    END IF;

    
    START TRANSACTION;

    INSERT INTO tb_users (email, nick, password)
    VALUES (p_email, p_nick, MD5(p_password));

    SET v_user_id = LAST_INSERT_ID();

    INSERT INTO tb_people (
        user_ID, courtesy_title, given_names, family_names,
        birth_date, gender, country_code, phone
    )
    VALUES (
        v_user_id, p_courtesy_title, p_given_names, p_family_names,
        p_birth_date, p_gender, p_country_code, p_phone
    );

    SET v_person_id = LAST_INSERT_ID();

    COMMIT;

    
    SELECT
        'Usuario y persona registrados correctamente' AS mensaje,
        v_user_id AS user_id,
        v_person_id AS person_id,
        p_email AS email,
        p_nick AS nick,
        v_db_user AS ejecutado_por,
        CURRENT_TIMESTAMP AS fecha_operacion;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
