/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_test_1_usa_users`()
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_gender VARCHAR(30);
    DECLARE v_courtesy VARCHAR(20);
    DECLARE v_given VARCHAR(150);
    DECLARE v_family VARCHAR(150);
    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_birth DATE;
    DECLARE v_phone VARCHAR(25);
    DECLARE v_seed VARCHAR(15);

    -- Prefijo basado en tiempo para evitar correos/nicks duplicados si corres el test varias veces
    SET v_seed = RIGHT(UNIX_TIMESTAMP(), 5);

    WHILE i <= 500 DO
        -- 50% Hombre / 50% Mujer con títulos de cortesía y nombres realistas de EE. UU.
        IF RAND() < 0.5 THEN
            SET v_gender = 'Hombre';
            SET v_courtesy = ELT(FLOOR(1 + RAND() * 3), 'Mr.', 'Dr.', '');
            SET v_given = ELT(FLOOR(1 + RAND() * 12), 
                'James', 'Michael', 'Robert', 'John', 'David', 'William', 
                'Richard', 'Joseph', 'Thomas', 'Christopher', 'Matthew', 'Daniel');
        ELSE
            SET v_gender = 'Mujer';
            SET v_courtesy = ELT(FLOOR(1 + RAND() * 4), 'Ms.', 'Mrs.', 'Dr.', '');
            SET v_given = ELT(FLOOR(1 + RAND() * 12), 
                'Mary', 'Patricia', 'Jennifer', 'Linda', 'Elizabeth', 'Barbara', 
                'Susan', 'Jessica', 'Sarah', 'Karen', 'Ashley', 'Emily');
        END IF;

        SET v_family = CONCAT(
            ELT(FLOOR(1 + RAND() * 12), 'Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Wilson', 'Taylor', 'Anderson', 'Thomas'),
            ' ',
            ELT(FLOOR(1 + RAND() * 10), 'Moore', 'Jackson', 'Martin', 'Lee', 'Thompson', 'White', 'Harris', 'Clark', 'Lewis', 'Walker')
        );

        -- Email y nick únicos y realistas
        SET v_nick = LOWER(CONCAT(v_given, '_', SUBSTRING_INDEX(v_family, ' ', 1), v_seed, i));
        SET v_email = CONCAT(v_nick, '@', ELT(FLOOR(1 + RAND() * 4), 'gmail.com', 'yahoo.com', 'outlook.com', 'icloud.com'));

        -- Fecha de nacimiento realista (entre 18 y 65 años)
        SET v_birth = DATE_SUB(CURRENT_DATE, INTERVAL FLOOR(6570 + RAND() * 17155) DAY);

        -- Teléfono formato EE. UU. (+1)
        SET v_phone = CONCAT('+1 (', FLOOR(200 + RAND() * 799), ') ', FLOOR(200 + RAND() * 799), '-', LPAD(FLOOR(RAND() * 9999), 4, '0'));

        CALL sp_register_new_user(
            v_email,
            v_nick,
            'PassTest2026!',
            v_courtesy,
            v_given,
            v_family,
            v_birth,
            v_gender,
            'US',
            v_phone
        );

        SET i = i + 1;
    END WHILE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
