DELIMITER ;;
CREATE DEFINER=`dara.gomez`@`%` PROCEDURE `sp_test_2_jovenes_paises`()
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_country_idx INT;
    DECLARE v_country VARCHAR(50);
    DECLARE v_phone_prefix VARCHAR(10);
    DECLARE v_gender VARCHAR(30);
    DECLARE v_courtesy VARCHAR(20);
    DECLARE v_given VARCHAR(150);
    DECLARE v_family VARCHAR(150);
    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_birth DATE;
    DECLARE v_phone VARCHAR(25);
    DECLARE v_days_old INT;
    DECLARE v_seed VARCHAR(15);
    DECLARE v_clean_given VARCHAR(50);
    DECLARE v_clean_family VARCHAR(50);

    SET v_seed = RIGHT(UNIX_TIMESTAMP(), 4);

    WHILE i <= 2000 DO
        -- Elegir país (1: MX, 2: CO, 3: AR, 4: ES, 5: US, 6: BR, 7: DE, 8: FR, 9: JP, 10: GB)
        SET v_country_idx = FLOOR(1 + RAND() * 10);

        IF RAND() < 0.5 THEN
            SET v_gender = 'Hombre';
        ELSE
            SET v_gender = 'Mujer';
        END IF;

        -- Generar datos culturalmente coherentes según el país seleccionado
        CASE v_country_idx
            WHEN 1 THEN -- México
                SET v_country = 'MX';
                SET v_phone_prefix = '+52 55';
                SET v_courtesy = IF(v_gender = 'Hombre', 'Sr.', 'Srita.');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Alejandro', 'Diego', 'Mateo', 'Sebastián', 'Emiliano', 'Carlos'),
                    ELT(FLOOR(1 + RAND() * 6), 'Sofía', 'Valentina', 'Camila', 'Ximena', 'Regina', 'Mariana'));
                SET v_family = CONCAT(
                    ELT(FLOOR(1 + RAND() * 6), 'Hernández', 'García', 'Martínez', 'López', 'González', 'Pérez'), ' ',
                    ELT(FLOOR(1 + RAND() * 6), 'Rodríguez', 'Sánchez', 'Ramírez', 'Cruz', 'Flores', 'Gómez'));

            WHEN 2 THEN -- Colombia
                SET v_country = 'CO';
                SET v_phone_prefix = '+57 310';
                SET v_courtesy = IF(v_gender = 'Hombre', 'Sr.', 'Sra.');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Santiago', 'Juan Pablo', 'Andrés', 'Camilo', 'Felipe', 'Nicolás'),
                    ELT(FLOOR(1 + RAND() * 6), 'Isabella', 'Salomé', 'Mariana', 'Gabriela', 'Daniela', 'Laura'));
                SET v_family = CONCAT(
                    ELT(FLOOR(1 + RAND() * 6), 'Rojas', 'Vargas', 'Moreno', 'Castro', 'Ortiz', 'Giraldo'), ' ',
                    ELT(FLOOR(1 + RAND() * 6), 'Muñoz', 'Restrepo', 'Cardona', 'Valencia', 'Mejía', 'Salazar'));

            WHEN 3 THEN -- Argentina
                SET v_country = 'AR';
                SET v_phone_prefix = '+54 11';
                SET v_courtesy = NULL;
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Bautista', 'Joaquín', 'Benjamín', 'Tomás', 'Facundo', 'Lucas'),
                    ELT(FLOOR(1 + RAND() * 6), 'Catalina', 'Martina', 'Delfina', 'Emilia', 'Agustina', 'Mía'));
                SET v_family = CONCAT(
                    ELT(FLOOR(1 + RAND() * 6), 'Fernández', 'Álvarez', 'Romero', 'Sosa', 'Torres', 'Ruiz'), ' ',
                    ELT(FLOOR(1 + RAND() * 6), 'Acosta', 'Benítez', 'Medina', 'Herrera', 'Suárez', 'Aguirre'));

            WHEN 4 THEN -- España
                SET v_country = 'ES';
                SET v_phone_prefix = '+34 612';
                SET v_courtesy = IF(v_gender = 'Hombre', 'D.', 'Dña.');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Hugo', 'Martín', 'Álvaro', 'Pablo', 'Adrián', 'Javier'),
                    ELT(FLOOR(1 + RAND() * 6), 'Lucía', 'Paula', 'Valeria', 'Alba', 'Claudia', 'Nerea'));
                SET v_family = CONCAT(
                    ELT(FLOOR(1 + RAND() * 6), 'Navarro', 'Domínguez', 'Gil', 'Vázquez', 'Serrano', 'Blanco'), ' ',
                    ELT(FLOOR(1 + RAND() * 6), 'Molina', 'Morales', 'Ortega', 'Delgado', 'Castro', 'Rubio'));

            WHEN 5 THEN -- Estados Unidos
                SET v_country = 'US';
                SET v_phone_prefix = '+1 415';
                SET v_courtesy = IF(v_gender = 'Hombre', 'Mr.', 'Ms.');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Liam', 'Noah', 'Ethan', 'Mason', 'Logan', 'Caleb'),
                    ELT(FLOOR(1 + RAND() * 6), 'Emma', 'Olivia', 'Ava', 'Sophia', 'Chloe', 'Madison'));
                SET v_family = CONCAT(
                    ELT(FLOOR(1 + RAND() * 6), 'Miller', 'Davis', 'Wilson', 'Taylor', 'Clark', 'Walker'), ' ',
                    ELT(FLOOR(1 + RAND() * 6), 'Hall', 'Allen', 'Young', 'King', 'Wright', 'Scott'));

            WHEN 6 THEN -- Brasil
                SET v_country = 'BR';
                SET v_phone_prefix = '+55 11';
                SET v_courtesy = IF(v_gender = 'Hombre', 'Sr.', 'Sra.');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Gabriel', 'Arthur', 'Heitor', 'Bernardo', 'Rafael', 'Thiago'),
                    ELT(FLOOR(1 + RAND() * 6), 'Helena', 'Alice', 'Laura', 'Manuela', 'Beatriz', 'Júlia'));
                SET v_family = CONCAT(
                    ELT(FLOOR(1 + RAND() * 6), 'Silva', 'Santos', 'Oliveira', 'Souza', 'Pereira', 'Costa'), ' ',
                    ELT(FLOOR(1 + RAND() * 6), 'Rodrigues', 'Almeida', 'Nascimento', 'Lima', 'Araújo', 'Carvalho'));

            WHEN 7 THEN -- Alemania
                SET v_country = 'DE';
                SET v_phone_prefix = '+49 151';
                SET v_courtesy = IF(v_gender = 'Hombre', 'Herr', 'Frau');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Lukas', 'Leon', 'Finn', 'Jonas', 'Felix', 'Maximilian'),
                    ELT(FLOOR(1 + RAND() * 6), 'Mia', 'Hannah', 'Lena', 'Lea', 'Clara', 'Anna'));
                SET v_family = ELT(FLOOR(1 + RAND() * 6), 'Müller', 'Schmidt', 'Schneider', 'Fischer', 'Weber', 'Meyer');

            WHEN 8 THEN -- Francia
                SET v_country = 'FR';
                SET v_phone_prefix = '+33 6';
                SET v_courtesy = IF(v_gender = 'Hombre', 'M.', 'Mme');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Léo', 'Gabriel', 'Raphaël', 'Louis', 'Jules', 'Arthur'),
                    ELT(FLOOR(1 + RAND() * 6), 'Jade', 'Louise', 'Ambre', 'Chloé', 'Manon', 'Camille'));
                SET v_family = ELT(FLOOR(1 + RAND() * 6), 'Martin', 'Bernard', 'Dubois', 'Thomas', 'Robert', 'Laurent');

            WHEN 9 THEN -- Japón
                SET v_country = 'JP';
                SET v_phone_prefix = '+81 90';
                SET v_courtesy = NULL;
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Haruto', 'Ren', 'Yuto', 'Sota', 'Kaito', 'Takumi'),
                    ELT(FLOOR(1 + RAND() * 6), 'Yui', 'Hina', 'Aoi', 'Sakura', 'Rin', 'Mio'));
                SET v_family = ELT(FLOOR(1 + RAND() * 6), 'Sato', 'Suzuki', 'Takahashi', 'Tanaka', 'Watanabe', 'Ito');

            ELSE -- Reino Unido
                SET v_country = 'GB';
                SET v_phone_prefix = '+44 7700';
                SET v_courtesy = IF(v_gender = 'Hombre', 'Mr.', 'Miss');
                SET v_given = IF(v_gender = 'Hombre',
                    ELT(FLOOR(1 + RAND() * 6), 'Oliver', 'George', 'Harry', 'Jack', 'Charlie', 'Alfie'),
                    ELT(FLOOR(1 + RAND() * 6), 'Amelia', 'Isla', 'Ava', 'Freya', 'Lily', 'Grace'));
                SET v_family = ELT(FLOOR(1 + RAND() * 6), 'Smith', 'Jones', 'Taylor', 'Brown', 'Williams', 'Davies');
        END CASE;

        -- Limpiar acentos/espacios para construir correos y nicks realistas y válidos
        SET v_clean_given = LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(v_given, ' ', ''), 'á', 'a'), 'é', 'e'), 'í', 'i'), 'ó', 'o'), 'ú', 'u'), 'ü', 'u'));
        SET v_clean_family = LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(v_family, ' ', 1), 'á', 'a'), 'é', 'e'), 'í', 'i'), 'ó', 'o'), 'ú', 'u'), 'ü', 'u'), 'ñ', 'n'));

        SET v_nick = CONCAT(v_clean_given, '.', v_clean_family, v_seed, i);
        SET v_email = CONCAT(v_nick, '@', ELT(FLOOR(1 + RAND() * 4), 'gmail.com', 'outlook.com', 'hotmail.com', 'proton.me'));

        -- Edad estrictamente entre 19 años (6935 días) y 35 años (12775 días)
        SET v_days_old = FLOOR(6935 + RAND() * (12775 - 6935));
        SET v_birth = DATE_SUB(CURRENT_DATE, INTERVAL v_days_old DAY);

        -- Teléfono realista con la lada del país
        SET v_phone = CONCAT(v_phone_prefix, ' ', FLOOR(100 + RAND() * 899), ' ', LPAD(FLOOR(RAND() * 9999), 4, '0'));

        CALL sp_register_new_user(
            v_email,
            v_nick,
            'PassTest2026!',
            v_courtesy,
            v_given,
            v_family,
            v_birth,
            v_gender,
            v_country,
            v_phone
        );

        SET i = i + 1;
    END WHILE;
END ;;
DELIMITER ;
