DELIMITER ;;
CREATE DEFINER=`dara.gomez`@`%` PROCEDURE `sp_test_3_probabilidad_estatus`()
BEGIN
    DECLARE i INT DEFAULT 1;
    DECLARE v_gender VARCHAR(30);
    DECLARE v_courtesy VARCHAR(20);
    DECLARE v_given VARCHAR(150);
    DECLARE v_family VARCHAR(150);
    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_birth DATE;
    DECLARE v_country VARCHAR(50);
    DECLARE v_phone VARCHAR(25);
    DECLARE v_is_active TINYINT(1);
    DECLARE v_seed VARCHAR(15);
    DECLARE v_clean_given VARCHAR(50);
    DECLARE v_clean_family VARCHAR(50);

    SET v_seed = RIGHT(UNIX_TIMESTAMP(), 4);

    WHILE i <= 5000 DO
        -- 48% Hombre, 48% Mujer, 4% Prefiero no decirlo (distribución realista)
        IF RAND() < 0.48 THEN
            SET v_gender = 'Hombre';
            SET v_courtesy = ELT(FLOOR(1 + RAND() * 4), 'Sr.', 'Mr.', 'Ing.', '');
            SET v_given = ELT(FLOOR(1 + RAND() * 15), 
                'Alejandro', 'Daniel', 'David', 'Pablo', 'Adrián', 'Javier', 'Fernando', 'Jorge',
                'Ricardo', 'Eduardo', 'Roberto', 'Héctor', 'Andrés', 'Mauricio', 'Gabriel');
        ELSEIF RAND() < 0.96 THEN
            SET v_gender = 'Mujer';
            SET v_courtesy = ELT(FLOOR(1 + RAND() * 4), 'Sra.', 'Ms.', 'Lic.', '');
            SET v_given = ELT(FLOOR(1 + RAND() * 15), 
                'María', 'Carmen', 'Ana', 'Laura', 'Paula', 'Andrea', 'Natalia', 'Gabriela',
                'Patricia', 'Mónica', 'Verónica', 'Diana', 'Carolina', 'Fernanda', 'Claudia');
        ELSE
            SET v_gender = 'Prefiero no decirlo';
            SET v_courtesy = NULL;
            SET v_given = ELT(FLOOR(1 + RAND() * 6), 'Alex', 'Dani', 'Cris', 'Sam', 'Andrea', 'Ariel');
        END IF;

        SET v_family = CONCAT(
            ELT(FLOOR(1 + RAND() * 15), 'García', 'Martínez', 'López', 'Sánchez', 'Pérez', 'Gómez', 'Ramírez', 'Cruz', 'Flores', 'Reyes', 'Morales', 'Vázquez', 'Jiménez', 'Ruiz', 'Díaz'),
            ' ',
            ELT(FLOOR(1 + RAND() * 15), 'Fernández', 'Hernández', 'Moreno', 'Álvarez', 'Ortiz', 'Castillo', 'Romero', 'Mendoza', 'Chávez', 'Ramos', 'Gutiérrez', 'Aguilar', 'Navarro', 'Salazar', 'Delgado')
        );

        -- Limpiar caracteres especiales para el email y nick
        SET v_clean_given = LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(v_given, 'á', 'a'), 'é', 'e'), 'í', 'i'), 'ó', 'o'), 'ú', 'u'));
        SET v_clean_family = LOWER(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(v_family, ' ', 1), 'á', 'a'), 'é', 'e'), 'í', 'i'), 'ó', 'o'), 'ú', 'u'), 'ñ', 'n'));

        SET v_nick = CONCAT(v_clean_given, '_', v_clean_family, v_seed, i);
        SET v_email = CONCAT(v_clean_given, '.', v_clean_family, v_seed, i, '@', ELT(FLOOR(1 + RAND() * 4), 'gmail.com', 'outlook.com', 'yahoo.com', 'icloud.com'));

        -- Edad realista entre 18 y 65 años
        SET v_birth = DATE_SUB(CURRENT_DATE, INTERVAL FLOOR(6570 + RAND() * 17155) DAY);

        -- País y teléfono coherente
        CASE FLOOR(1 + RAND() * 5)
            WHEN 1 THEN SET v_country = 'MX'; SET v_phone = CONCAT('+52 55 ', FLOOR(1000 + RAND() * 8999), ' ', LPAD(FLOOR(RAND() * 9999), 4, '0'));
            WHEN 2 THEN SET v_country = 'US'; SET v_phone = CONCAT('+1 305 ', FLOOR(200 + RAND() * 799), '-', LPAD(FLOOR(RAND() * 9999), 4, '0'));
            WHEN 3 THEN SET v_country = 'ES'; SET v_phone = CONCAT('+34 6', FLOOR(10 + RAND() * 89), ' ', FLOOR(100 + RAND() * 899), ' ', FLOOR(100 + RAND() * 899));
            WHEN 4 THEN SET v_country = 'CO'; SET v_phone = CONCAT('+57 320 ', FLOOR(200 + RAND() * 799), ' ', LPAD(FLOOR(RAND() * 9999), 4, '0'));
            ELSE        SET v_country = 'AR'; SET v_phone = CONCAT('+54 11 ', FLOOR(4000 + RAND() * 5999), '-', LPAD(FLOOR(RAND() * 9999), 4, '0'));
        END CASE;

        CALL sp_register_new_user(
            v_email,
            v_nick,
            'PassTest2026!',
            v_courtesy,
            v_given,
            v_family,
            v_birth,
            v_gender,
            v_country,
            v_phone
        );

        -- 80% probabilidad Activo (1), 20% Inactivo (0)
        IF RAND() <= 0.80 THEN
            SET v_is_active = 1;
        ELSE
            SET v_is_active = 0;
        END IF;

        -- Recuerda verificar que la columna en tb_users se llame 'status' (o cámbiala por is_active / active)
        UPDATE tb_users 
        SET status = v_is_active 
        WHERE email = v_email;

        SET i = i + 1;
    END WHILE;
END ;;
